#!/usr/bin/env bash
# Link VS Code settings/keybindings and install the extensions in extensions.txt.
# Safe to re-run.
set -euo pipefail
source "$(dirname "$0")/../_apply/lib.sh"
V="$DOTFILES/shared/vscode"

case "$(uname -s)" in
    Darwin) user_dir="$HOME/Library/Application Support/Code/User"; os=macos ;;
    Linux)  user_dir="$HOME/.config/Code/User"; os=linux ;;
    *) echo "setup-vscode: unsupported OS" >&2; exit 1 ;;
esac

link "$V/$os-settings.jsonc"                   "$user_dir/settings.json"
# Generated by keybinds-gen/generate.py; the output is committed.
link "$V/keybinds-gen/out/keybinds.$os.json"   "$user_dir/keybindings.json"

if ! command -v code >/dev/null; then
    echo "setup-vscode: 'code' not on PATH, skipping extensions" >&2
    exit 0
fi
installed=$(code --list-extensions | tr '[:upper:]' '[:lower:]')
while IFS= read -r ext; do
    [ -z "$ext" ] && continue
    printf '%s\n' "$installed" | grep -qxF "$(printf '%s' "$ext" | tr '[:upper:]' '[:lower:]')" && continue
    code --install-extension "$ext"
done < "$V/extensions.txt"
